'use strict';
/* path routing (generated by skyline-seo-build) */
const BASE=(()=>{if(window.__SKYLINE_BASE__)return window.__SKYLINE_BASE__;const s=document.currentScript&&document.currentScript.src;return s?new URL('.',s).pathname:'/';})();
const U=p=>BASE+p;
function hashToPath(h){const parts=String(h).replace(/^#\/?/,'').split('/').filter(Boolean),p=parts[0];if(p==='building'&&parts[1])return U('building/'+parts[1]+'/')+(parts[2]?'#b'+parts[1]+'-'+parts[2]:'');if(p==='ranking'&&parts[1]==='method')return U('method/');if(['visit','compare'].includes(p))return U(p+'/');if(p==='learn')return U('learn/')+(parts[1]?'#learn-'+parts[1]:'');return U('');}
function navigate(url){window.history.pushState(null,'',url);route();}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const credit=i=>`${link(i.source,esc(i.author)+' / Wikimedia Commons')} · ${link(i.licenseUrl,esc(i.license))}${i.changes?' · '+esc(i.changes):''}`;
const routeLink=(id,label)=>`<a href="${U('building/'+id+'/')}">${esc(label)}</a>`;
const majorContractors=['大林組','鹿島建設','清水建設','大成建設','竹中工務店','戸田建設','前田建設工業','西松建設','熊谷組','鴻池組'];
const companyKey=s=>String(s).replace(/（[^）]*）|\([^)]*\)/g,'').replace(/株式会社|合同会社/g,'').trim();
const searchKey=s=>String(s||'').normalize('NFKC').toLocaleLowerCase('ja');
const majorDevelopers=[
 {key:'三井不動産',label:'三井不動産グループ',aliases:['三井不動産']},
 {key:'住友不動産',label:'住友不動産',aliases:['住友不動産']},
 {key:'森ビル',label:'森ビル',aliases:['森ビル']},
 {key:'三菱地所',label:'三菱地所グループ',aliases:['三菱地所']},
 {key:'東京建物',label:'東京建物',aliases:['東京建物']},
 {key:'野村不動産',label:'野村不動産',aliases:['野村不動産']},
 {key:'東急不動産',label:'東急不動産',aliases:['東急不動産']},
 {key:'NTT都市開発',label:'NTT都市開発',aliases:['NTT都市開発','エヌ・ティ・ティ都市開発']},
 {key:'JR東海',label:'JR東海',aliases:['JR東海','東海旅客鉄道','ジェイアールセントラルビル']},
 {key:'近鉄',label:'近鉄',aliases:['近畿日本鉄道','近鉄不動産']}
];
function developerGroupNames(b){const text=(b.filterDevelopers||b.construction?.developers||[]).join(' ').normalize('NFKC');return majorDevelopers.filter(g=>g.aliases.some(n=>text.includes(n))).map(g=>g.key);}
function matchesDeveloper(b,key){const groups=developerGroupNames(b);return !key||(key==='other'?groups.length===0:groups.includes(key));}
function developerOptions(){const groups=majorDevelopers.map(g=>[g.key,`${g.label}（${buildings.filter(b=>developerGroupNames(b).includes(g.key)).length}棟）`]);groups.push(['other',`その他（${buildings.filter(b=>!developerGroupNames(b).length).length}棟）`]);return groups;}
const defaults={q:'',city:'',access:'',decade:'',developer:'',contractor:'',use:'',range:'',hotel:false,sort:'height',dir:'desc',view:'table'};
let saved={};try{saved=JSON.parse(sessionStorage.getItem('skyline-filters-v7')||'{}')}catch(e){}
if(saved.developer&&!majorDevelopers.some(g=>g.key===saved.developer)&&saved.developer!=='other'){const old=saved.developer.normalize('NFKC');saved.developer=majorDevelopers.find(g=>g.aliases.some(n=>old.includes(n)))?.key||'other';}
let state={...defaults,...saved},currentPage='',currentBuilding=null,homeScroll=0;
function saveState(){try{sessionStorage.setItem('skyline-filters-v7',JSON.stringify(state))}catch(e){}}
const developerLabel=b=>(b.filterDevelopers||b.construction?.developers||[]).filter(n=>n&&!/未確認|不明|市街地再開発組合/.test(n)).map(companyKey).slice(0,2).join(' / ')||'公開資料では確認できず';
function uses(b){if(b.tags?.length)return b.tags;const c=b.contents||{},f=(b.floorComposition||[]).join(' '),a=[];if(c.offices?.length||/オフィス/.test(f))a.push('オフィス');if(c.hotels?.length)a.push('ホテル');if(/住宅|レジデンス|マンション/.test((b.use||'')+f))a.push('住宅');return a.length?a:[b.use||'複合'];}
const contractors=b=>(b.construction?.filterContractors||b.construction?.contractors||[]).map(companyKey).filter(n=>!(/未確認|不明|確認できず/.test(n)));
function visitType(b,type){const rs=(b.visitOptions||[]).map(v=>v.requirement+' '+v.name).join(' ');if(type==='open')return b.hasObservation&&b.observationOpen;if(type==='free')return (b.observationOpen&&/無料/.test(b.visitor?.price||''))||/(?:無料(?:で|。|、|\s|・|$)|入場料(?:は)?不要|自由見学|一般来館)/.test(rs);if(type==='food')return /飲食利用|食事利用|カフェ・バーの利用/.test(rs);if(type==='stay')return Boolean(b.contents?.hotels?.length);return true;}
function sortedBuildings(list){return [...list].sort((a,b)=>{const key=state.sort,av=key==='observation'?Number(a.hasObservation&&a.observationOpen):a[key],bv=key==='observation'?Number(b.hasObservation&&b.observationOpen):b[key];const result=typeof av==='string'?String(av).localeCompare(String(bv),'ja'):Number(av)-Number(bv);return result*(state.dir==='desc'?-1:1)||a.rank-b.rank;});}
function filteredBuildings(){const q=searchKey(state.q).trim(),r=state.range.split(':').map(Number);return sortedBuildings(buildings.filter(b=>(!state.city||b.city===state.city)&&visitType(b,state.access)&&(!state.hotel||b.contents?.hotels?.length)&&(!state.use||uses(b).includes(state.use))&&(!state.decade||Math.floor(b.year/10)*10===+state.decade)&&matchesDeveloper(b,state.developer)&&(!state.contractor||(state.contractor==='other'?contractors(b).some(n=>!majorContractors.some(m=>n.includes(m))):contractors(b).some(n=>n.includes(state.contractor))))&&(!state.range||b.rank>=r[0]&&b.rank<=r[1])&&(!q||searchKey([b.name,b.city,b.address,...Object.values(b.contents||{}).flat(),...(b.construction?.developers||[]),...(b.visitOptions||[]).flatMap(v=>[v.name,v.activity])].join(' ')).includes(q))));}
function accessLabel(b){return b.hasObservation?(b.observationOpen?'展望台あり':'展望フロア休業中'):(b.visitOptions?.some(v=>/飲食|食事|カフェ/.test(v.requirement))?'高層階で食事':b.contents?.hotels?.length?'ホテル入居':'一般向け展望台なし');}
function photoPlaceholder(label){return `<span class="photo-wait"><svg viewBox="0 0 80 110" width="48" height="66" aria-hidden="true"><path d="M12 104V32h16V15h24v17h16v72Z" fill="#d8e0e5" stroke="#93a6b3" stroke-width="2"/><path d="M33 22h14M24 44h32M24 56h32M24 68h32M24 80h32M33 93h14" fill="none" stroke="#a5b6c1" stroke-width="3"/><path d="M6 105h68" stroke="#93a6b3" stroke-width="2"/></svg><span class="photo-label">${esc(label)}</span></span>`;}
function photo(b,cls='',lazy=true){const compact=cls.includes('table-photo'),w=compact?64:600,h=compact?86:800;return `<span class="photo-frame ${cls}" data-photo-state="${b.image?'loading':'missing'}">${photoPlaceholder(b.image?'読込中':'写真未掲載')}${b.image?`<img src="${esc(lazy?(b.image.displayUrl||b.image.url):b.image.url)}" alt="${esc(b.name)}の外観" width="${w}" height="${h}" ${lazy?'loading="lazy"':'loading="eager"'} decoding="async" referrerpolicy="no-referrer" data-building-photo>`:''}</span>`;}
function cardHTML(b){return `<a class="rank-card" href="${U('building/'+b.id+'/')}"><div class="card-photo">${photo(b)}</div><div class="card-copy"><span class="card-rank">全国 ${b.rank}位</span><h3>${esc(b.name)}</h3><div class="card-numbers"><strong class="num">${b.height}<small>m</small></strong><span>${esc(b.city)}</span></div></div></a>`;}
function tableHTML(list){const cols=[['rank','順位'],['','写真'],['name','ビル名'],['height','高さ'],['floors','階数'],['year','竣工年'],['city','都市'],['observation','展望台']];return `<table class="rank-table"><caption class="sr-only">日本の超高層ビルランキング。列見出しで並べ替えできます。</caption><colgroup><col class="col-rank"><col class="col-photo"><col class="col-name"><col class="col-height"><col class="col-floors"><col class="col-year"><col class="col-city"><col class="col-observation"></colgroup><thead><tr>${cols.map(([key,label])=>`<th scope="col" ${key?`aria-sort="${state.sort===key?(state.dir==='asc'?'ascending':'descending'):'none'}"`:''} class="${['height','floors','year'].includes(key)?'right':''}">${key?`<button data-sort="${key}" aria-label="${label}で並べ替え">${label} ${state.sort===key?(state.dir==='asc'?'↑':'↓'):'↕'}</button>`:'<span class="sr-only">写真</span>'}</th>`).join('')}</tr></thead><tbody>${list.map(b=>`<tr><td class="rank-cell num">${b.rank}</td><td class="photo-cell"><a class="table-photo-link" href="${U('building/'+b.id+'/')}" aria-label="${esc(b.name)}の詳細">${photo(b,'table-photo')}</a></td><td class="building-cell"><a class="building-name" href="${U('building/'+b.id+'/')}"><strong>${esc(b.name)}</strong><small>${esc(developerLabel(b))}</small></a></td><td class="right table-height num">${b.height}<small>m</small></td><td class="right num">${b.floors}階</td><td class="right num">${b.year}年</td><td>${esc(b.city)}</td><td><span class="pill ${b.observationOpen?'open':''}">${b.hasObservation?(b.observationOpen?'営業中':'休業中'):'なし'}</span><a class="table-link" href="${U('building/'+b.id+'/')}#b${b.id}-visit">利用できる場所</a></td></tr>`).join('')}</tbody></table>`;}
function options(arr,value,first){return `<option value="">${esc(first)}</option>`+arr.map(v=>{const [key,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(key)}" ${String(key)===String(value)?'selected':''}>${esc(label)}</option>`}).join('');}
function field(id,label,html){return `<div class="filter-field"><label for="${id}">${label}</label>${html}</div>`;}
function methodHTML(){return `<details class="method" id="ranking-method"><summary>集計基準・高さの定義・出典</summary><p>2026年10月18日時点で竣工済みの建築物、全国100位までを掲載しています。同率100位が2棟あるため、掲載は101棟です。同じ高さは同順位とし、次順位は棟数に応じて進みます。絞り込み中も全国順位を維持します。</p><p>高さは原則として出典に記載された建築物最高部（アンテナを除く）。竣工年と開業年は区別し、電波塔・建設中・計画中の建物はランキングに含めません。施工JV・開発事業主は確認できた当時の情報を記載しています。</p><p>${link('https://skyskysky.net/003-list.html','全国の超高層ビル一覧')} · ${link('https://www.kajima.co.jp/news/digest/apr_2018/feature/step/index-j.html','鹿島・日本の超高層建築の歴史')}。個々の公式発表・施設の営業案内・写真のライセンスは各ビル詳細の出典をご覧ください。</p><details class="data-note"><summary>トップ写真のクレジット</summary><p>${credit(heroImage)}</p></details></details>`;}
function renderMethod(){document.title='集計基準・高さの定義・出典｜SKYLINE JAPAN';$('#app').innerHTML=`<div class="wrap"><nav class="breadcrumbs" aria-label="パンくず"><a href="${U('')}">ランキング</a><span aria-hidden="true">›</span><span>集計基準・出典</span></nav><div class="page-head"><p class="page-kicker">ランキングについて</p><h1 tabindex="-1">集計基準・高さの定義・出典</h1><p>掲載範囲、順位の付け方、高さの定義と主な出典をまとめています。</p></div>${methodHTML().replace('<details class="method" id="ranking-method">','<details class="method" id="ranking-method" open>')}<p style="margin-top:24px"><a href="${U('')}">← ランキングへ戻る</a></p></div>`;}
function renderHome(){const cities=[...new Set(buildings.map(b=>b.city))],devs=developerOptions(),decades=[...new Set(buildings.map(b=>Math.floor(b.year/10)*10))].sort().map(n=>[n,`${n}年代`]);$('#app').innerHTML=`<div class="wrap"><section class="intro-hero" aria-labelledby="home-title"><div><p class="page-kicker">日本の高層建築を、知って、訪ねる。</p><h1 id="home-title" tabindex="-1">日本の超高層ビルランキング</h1><p>高さ・建築データから、展望台や食事で行けるフロアまで。<br>全国100位までのビルを調べて、次の行き先を見つけよう。</p><div class="intro-meta"><span>竣工済み101棟</span><span>全国100位まで・同率含む</span><span>2026年10月更新</span></div></div><div class="hero-photo" style="background-image:url('${esc(heroImage.url)}')" role="img" aria-label="麻布台ヒルズと東京タワーを含む東京の夜景"><div class="hero-stat">日本一のビル<strong><span id="hero-count">325.49</span><small> m</small></strong>麻布台ヒルズ森JPタワー</div></div></section><section class="ranking-section" aria-label="ランキング"><div class="section-heading"><h2>ビルを探す</h2></div><div class="filter-box"><div class="filter-primary">${field('building-search','ビル名・地名・施設名',`<input id="building-search" type="search" value="${esc(state.q)}" placeholder="例：新宿、ハルカス、ホテル名" autocomplete="off">`)}${field('city','都市',`<select id="city">${options(cities,state.city,'すべての都市')}</select>`)}${field('access','展望・高層階の利用',`<select id="access">${options([['open','展望台あり（営業中）'],['free','無料で利用できる場所'],['food','高層階で食事・カフェ'],['stay','ホテル入居あり']],state.access,'すべての利用条件')}</select>`)}</div><details class="filter-more"><summary>さらに絞り込む</summary><div class="advanced-fields">${field('decade','竣工年代',`<select id="decade">${options(decades,state.decade,'すべての年代')}</select>`)}${field('developer','主なデベロッパー',`<select id="developer">${options(devs,state.developer,'すべての事業主')}</select>`)}${field('contractor','主な施工会社',`<select id="contractor">${options([...majorContractors,['other','その他の施工会社']],state.contractor,'すべての施工会社')}</select>`)}${field('rank-range','全国順位',`<select id="rank-range">${options([['1:25','1～25位'],['26:50','26～50位'],['51:75','51～75位'],['76:100','76～100位']],state.range,'100位まで、すべて')}</select>`)}</div><div class="filter-checks">${field('use','建物の用途',`<select id="use">${options(['オフィス','ホテル','住宅'],state.use,'すべての用途')}</select>`)}<label><input id="hotel-only" type="checkbox" ${state.hotel?'checked':''}>ホテル入居あり</label></div><p class="small muted">事業主は主要10社・グループとその他に整理。再開発組合の物件は確認できた主な参加企業で分類し、住宅子会社は同じグループに含めています。共同事業は複数の条件に該当します。施工会社も公開資料で確認できた範囲です。</p></details><div class="filter-actions"><button id="reset-filters">条件を解除</button><span class="small muted">全国順位は絞り込み後も維持</span></div></div><div class="results-toolbar"><p id="result-count" aria-live="polite"></p><div class="view-controls"><select id="mobile-sort" class="mobile-sort" aria-label="並べ替え">${options([['height:desc','高さが高い順'],['height:asc','高さが低い順'],['rank:asc','全国順位順'],['year:desc','竣工が新しい順'],['name:asc','名前順']],state.sort+':'+state.dir,'並べ替え')}</select><div class="view-switch" aria-label="ランキングの表示形式"><button data-view="table" aria-pressed="${state.view==='table'}">表</button><button data-view="cards" aria-pressed="${state.view==='cards'}">カード</button></div></div></div><div id="rank-results"></div><p class="result-note">高さは建物最高部。地上階数を記載しています。ビル名から、行ける階・施設・建築データを確認できます。</p>${methodHTML()}</section><nav class="explore-links" aria-label="もっと楽しむ"><a href="${U('visit/')}"><strong>展望台を選ぶ →</strong><span>料金・営業時間・入場条件を比較</span></a><a href="${U('compare/')}"><strong>高さを比べる →</strong><span>同じ縮尺でビルとタワーを見比べる</span></a><a href="${U('learn/')}"><strong>歴史・クイズ・計算機 →</strong><span>摩天楼をもっと楽しむ</span></a></nav></div>`;$('#header-search').value=state.q;renderResults();animateHeroCount();}
function renderResults(){const list=filteredBuildings();$('#result-count').innerHTML=`<strong class="num">${list.length}</strong>棟 <span class="small">／全${buildings.length}棟</span>`;$('#rank-results').innerHTML=list.length?`<div class="rank-table-wrap" ${state.view==='table'?'':'hidden'}>${tableHTML(list)}</div><div class="ranking-cards" ${state.view==='cards'?'':'hidden'}>${list.map(cardHTML).join('')}</div>`:'<div class="empty-state"><h3>該当するビルがありません</h3><p>検索語や絞り込み条件を変えてください。</p><button data-reset>条件を解除する</button></div>';$$('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===state.view));saveState();}
function uniqueSources(list){return list.filter((s,i,a)=>s&&s.url&&a.findIndex(x=>x.url===s.url)===i)}
function sourceTags(b){const list=uniqueSources([...(b.constructionSources||[]).slice(0,1),...(b.contentSources||[]).slice(0,1),...(b.sourceLinks||[])]).slice(0,3);return [...list,...(b.image?[{label:'写真クレジット',url:b.image.source}]:[])].map(s=>link(s.url,esc(s.label))).join('')}
function sourceArchive(b){const groups=[['建物データ',[...(b.constructionSources||[]),...(b.developerGroupSources||[])]],['入居企業・館内施設',b.contentSources||[]],['展望台・ホテルの利用条件',b.access?.sources||[]],['施設・基本情報',[...(b.sourceLinks||[]),...(b.visitSources||[])]]];const count=uniqueSources(groups.flatMap(g=>g[1])).length;return `<details class="source-archive"><summary>項目別の確認資料を見る（${count}件）</summary>${groups.filter(g=>g[1].length).map(g=>`<h4>${g[0]}</h4><ul>${uniqueSources(g[1]).map(v=>`<li>${link(v.url,esc(v.label))}</li>`).join('')}</ul>`).join('')}</details>`}
function listHTML(arr){if(!arr?.length)return '公開資料では確認できず';return `<ul>${arr.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`}
function constructionTable(b){const c=b.construction;if(!c)return '<p class="informationnote">建築データは公開資料で確認できた範囲を掲載しています。</p>';const contractors=c.contractors.length>7?`<details class="jv-list"><summary>${c.contractorScope?'街区全体の施工':'施工JV'} ${c.contractors.length}社を表示</summary>${listHTML(c.contractors)}</details>`:listHTML(c.contractors);return `<table class="data-table"><caption class="sr-only">建物データ</caption><tbody><tr><th scope="row">着工年月</th><td>${esc(c.start||'公開資料では確認できず')}</td></tr><tr><th scope="row">竣工年月</th><td>${esc(c.completion||'公開資料では確認できず')}</td></tr><tr><th scope="row">施工会社${c.contractorScope?'<br>（街区全体の記録）':''}</th><td>${contractors}</td></tr><tr><th scope="row">設計・デザイン</th><td>${listHTML(c.designers)}</td></tr><tr><th scope="row">デベロッパー<br>（事業主）</th><td>${listHTML(c.developers)}</td></tr></tbody></table>${c.notes?`<details class="data-note"><summary>建築データについての補足</summary><p>${esc(c.notes)}</p></details>`:''}`}
function floorScore(text,maxFloor=100){const t=text.normalize('NFKC');if(/屋上/.test(t))return maxFloor+1;if(/中高層|中層/.test(t)&&!/[0-9]/.test(t))return maxFloor*.5;if(/上部|高層|上層/.test(t)&&!/[0-9]/.test(t))return maxFloor*.8;if(/低層/.test(t)&&!/[0-9]/.test(t))return 0;const head=t.split(/[：:]/)[0];const ns=[...head.matchAll(/(B)?(\d+)(?=階|F|[~〜～–—−-]|・|$)/gi)].map(m=>(m[1]?-1:1)*Number(m[2]));return ns.length?Math.max(...ns):-100;}
function floorsTopDown(b){return (b.floorComposition||[]).flatMap(v=>v.split(/[、,]/).map(t=>t.trim()).filter(Boolean)).map((v,i)=>({v,i,score:floorScore(v,b.floors)})).sort((a,b)=>b.score-a.score||a.i-b.i).map(v=>v.v);}
function hotelDetails(b){if(!b.contents?.hotels?.length)return '';const hs=b.hotelLinks||[];return `<h3>ホテル・公式予約</h3>${hs.length?hs.map(h=>`<article class="hotel-info"><h4>${link(h.url,esc(h.name))}</h4>${h.note?`<p>${esc(h.note)}</p>`:''}</article>`).join(''):listHTML(b.contents.hotels)}`;}
function facilityDetails(b){const c=b.contents;if(!c)return `<h3>館内施設</h3><p>${esc(b.tenants||'')}</p><p>${esc(b.shops||'')}</p>`;const groups=[['offices','主なオフィス入居企業'],['retail','ショップ・レストラン'],['other','その他の施設']];return `<h3>フロア構成 <small class="heading-note">上層階 → 地下階</small></h3><ol class="floorlist">${floorsTopDown(b).map(f=>`<li>${esc(f)}</li>`).join('')}</ol>${hotelDetails(b)}<div class="facility-section">${groups.map(([key,label])=>c[key]?.length?`<h3>${label}</h3>${listHTML(c[key].slice(0,key==='offices'||key==='retail'?10:20))}`:'').join('')}</div>${b.informationNote?`<details class="data-note"><summary>館内施設についての補足</summary><p>${esc(b.informationNote)}</p></details>`:''}`}
function observationDetails(b){const v=b.visitor;if(!b.hasObservation)return '<p class="no-observation">一般向け展望台：なし</p>';return `<article class="observation-info"><h4>${v?.url?link(v.url,esc(v.name)):esc(v?.name||'展望施設')}</h4><dl><div><dt>営業状況</dt><dd>${b.observationOpen?'営業中':'休業中'}</dd></div><div><dt>営業時間</dt><dd>${esc(v?.hours||'最新の営業日・時間は施設公式でご確認ください。')}</dd></div><div><dt>料金</dt><dd>${esc(v?.price||'営業日により異なります。公式料金表をご確認ください。')}</dd></div></dl><p>${esc(v?.note||b.observation)}</p></article>`;}
function visitDetails(b){const vs=[...(b.visitOptions||[])].sort((x,y)=>floorScore(y.floor||'',b.floors)-floorScore(x.floor||'',b.floors));return `<h3>ここでできること・上の階への行き方</h3><p class="visit-intro">確認できた来館先を上の階から紹介。各施設の利用範囲内で楽しめます。</p>${vs.length?`<div class="visit-options">${vs.map(v=>`<article class="visit-option"><div class="visit-floor">${esc(v.floor||'館内')}</div><div><h4>${esc(v.name)}</h4><p>${esc(v.activity)}</p><p class="visit-requirement"><strong>利用に必要なもの</strong>${esc(v.requirement)}</p>${v.url?link(v.url,'公式案内・予約'):''}</div></article>`).join('')}</div>`:`<p>${esc(b.visitNote||'一般来館で利用できる高層の展望・飲食施設は確認できていません。')}</p>`}`;}
function accessDetails(b){const a=b.access||{};return `<section class="access-panel" aria-label="このビルの展望・入館案内"><h3>展望・お出かけガイド</h3>${observationDetails(b)}${visitDetails(b)}${a.public?`<details class="access-notes"><summary>一般来館の補足</summary><p>${esc(a.public)}</p></details>`:''}${b.contents?.hotels?.length?`<details class="access-notes"><summary>ホテル宿泊で利用できる範囲</summary><p>${esc(a.hotel||'予約した客室・プランに付帯する施設を利用できます。客室階の指定や上層階の確約はホテルへ確認してください。')}</p></details>`:''}</section>`}
function mapEmbed(b){return `<div class="building-map"><iframe title="${esc(b.name)}のGoogleマップ" src="https://maps.google.com/maps?hl=ja&amp;q=${encodeURIComponent(b.name+' '+b.address)}&amp;z=16&amp;output=embed" width="100%" height="340" style="border:0" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="map-actions">${link(b.map,'Googleマップを開く')}${link('https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(b.name+' '+b.address),'ここへの経路を調べる')}</div>`;}
function highestOptions(b){return [...(b.visitOptions||[])].filter(v=>!(/現在入場不可|現在は営業休止|再開日/.test(v.requirement+' '+v.floor))).sort((a,c)=>floorScore(c.floor||'',b.floors)-floorScore(a.floor||'',b.floors));}
function renderBuilding(id){const b=buildings.find(x=>x.id===+id);if(!b){$('#app').innerHTML=`<div class="wrap page-head"><h1>ビルが見つかりません</h1><a href="${U('')}">ランキングへ戻る</a></div>`;return;}currentBuilding=b.id;document.title=b.name+'｜SKYLINE JAPAN';const tops=highestOptions(b).slice(0,2),toc=[['overview','概要'],['visit','行ける場所・展望台'],['floors','フロア・施設'],['access','アクセス・地図'],['data','建物データ'],['sources','出典']];$('#app').innerHTML=`<article class="wrap building-page"><nav class="breadcrumbs" aria-label="パンくず"><a href="${U('')}">ランキング</a><span aria-hidden="true">›</span><span>${esc(b.name)}</span></nav><a class="back-link" href="${U('')}">← ランキングに戻る</a><div class="building-intro"><figure class="building-figure">${b.image?`<button class="photo-enlarge" data-photo-id="${b.id}" aria-label="${esc(b.name)}の外観写真を拡大">${photo(b,'',false)}<span>写真を拡大 ⤢</span></button>`:`<div class="photo-enlarge">${photo(b)}</div>`}${b.image?`<figcaption>${esc(b.image.caption||b.name+'の外観')}<br>${credit(b.image)}</figcaption>`:''}</figure><div class="building-summary"><p class="building-rank">全国 ${b.rank}位 · ${esc(b.city)} · ${esc(uses(b).join('／'))}</p><h1 id="building-title" tabindex="-1">${esc(b.name)}</h1><dl class="basic-grid"><div><dt>高さ</dt><dd>${b.height}<small>m</small></dd></div><div><dt>地上階数</dt><dd>${b.floors}<small>階</small></dd></div><div><dt>竣工年</dt><dd>${b.year}<small>年</small></dd></div></dl><p class="summary-text">${esc(b.fact)}</p><p class="summary-place">${esc(b.address)}<br>最寄駅：${esc(b.station)}</p><div class="highest-box"><h2>一般客が利用できる高層階</h2>${tops.length?tops.map(v=>`<p><strong>${esc(v.floor)}</strong>　${esc(v.name)}</p>`).join(''):`<p>${b.hasObservation&&!b.observationOpen?'展望フロアは現在休業中です。':'高層階への一般向け訪問ルートは確認できていません。'}</p>`}<a href="${U('building/'+b.id+'/')}#b${b.id}-visit">必要な予約・利用条件を確認 ↓</a></div></div></div><div class="detail-layout"><nav class="detail-toc" aria-label="ビル詳細の目次"><strong>このページの目次</strong>${toc.map(([key,label])=>`<a href="${U('building/'+b.id+'/')}#b${b.id}-${key}" data-section="${key}">${label}</a>`).join('')}</nav><div class="detail-content"><section class="detail-section" id="b${b.id}-overview"><h2>このビルについて</h2>${(b.profile||[b.fact]).map(p=>`<p>${esc(p)}</p>`).join('')}</section><section class="detail-section" id="b${b.id}-visit"><h2>行ける場所・展望台</h2>${accessDetails(b)}<p class="small muted">利用条件の確認：${esc(b.checkedAt||'2026年10月19日')}。客室階の希望や眺望席の指定は予約時に確認してください。</p></section><section class="detail-section" id="b${b.id}-floors"><h2>フロア・テナントとショップ</h2>${facilityDetails(b)}</section><section class="detail-section" id="b${b.id}-access"><h2>アクセス・地図</h2><p>${esc(b.address)}<br>最寄駅：${esc(b.station)}</p>${mapEmbed(b)}<p class="small muted">ホテル・展望台・レストランは入口やエレベーターが別の場合があります。上の利用案内と公式アクセス案内を合わせてご覧ください。</p></section><section class="detail-section" id="b${b.id}-data"><h2>建物データ</h2>${constructionTable(b)}</section><section class="detail-section" id="b${b.id}-sources"><h2>出典・更新情報</h2><p>確認日：${esc(b.checkedAt||'2026年10月18日')}。入居企業・店舗は公開情報で確認できた主要な例です。</p><div class="source-tags">${sourceTags(b)}</div>${sourceArchive(b)}${b.image?`<h3>写真クレジット</h3><p class="credit">${credit(b.image)}</p>`:''}</section><div class="detail-end"><a href="${U('')}">← 条件を保ってランキングへ</a><a href="${U('visit/')}">展望台ガイドを見る →</a><button data-copy-url>このビルのURLをコピー</button><span id="copy-status" class="small" role="status"></span></div></div></div></article>`;}
