const questionPool=[[1,2],[1,3],[1,4],[1,5],[1,6],[1,8],[1,11],[1,14],[1,18],[2,5],[2,6],[2,9],[2,12],[2,16],[3,7],[3,10],[3,15],[4,8],[4,13],[5,20]];
let qi=0,score=0,answered=false,pairs=[];
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
function startQuiz(){qi=0;score=0;answered=false;pairs=shuffle(questionPool).slice(0,5).map(p=>shuffle(p));renderQuiz();}
function renderQuiz(){answered=false;if(qi===5){const title=score===5?'摩天楼マスター':score>=3?'スカイライン探検家':score>=1?'見上げる冒険者':'摩天楼ルーキー';$('#quizbox').innerHTML=`<p class="quizprogress">結果発表</p><h3 class="quizscore num">${score}<small>／5問正解</small></h3><h3>${title}</h3><p>20問のプールからランダムに5問。次は別の組み合わせで挑戦できます。</p><button class="quiznext" data-quiz-restart>もう一度挑戦</button>`;return;}const pair=pairs[qi].map(id=>buildings.find(b=>b.id===id));$('#quizbox').innerHTML=`<p class="quizprogress">第${qi+1}問／5問　·　現在${score}問正解</p><h3>より高いビルはどっち？</h3><div class="quizchoices">${pair.map(b=>`<button data-choice="${b.id}">${esc(b.name)}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div>`;}
function answerQuiz(id){if(answered||qi>=5)return;answered=true;const pair=pairs[qi].map(id=>buildings.find(b=>b.id===id)),correct=pair[0].height>pair[1].height?pair[0]:pair[1],ok=id===correct.id;if(ok)score++;$$('[data-choice]').forEach(x=>{x.disabled=true;x.classList.add(+x.dataset.choice===correct.id?'correct':'wrong')});$('#feedback').innerHTML=`<h4 class="answerstatus">${ok?'正解！':'不正解'}　${esc(correct.name)}の方が高い</h4>${pair.map(b=>`<div class="answerfact"><b>${esc(b.name)}　<span class="num">${b.height}m</span></b><p>${esc(b.fact)}</p>${routeLink(b.id,'このビルを詳しく見る →')}</div>`).join('')}<button class="quiznext" data-quiz-next>${qi===4?'結果を見る':'次の問題へ'} →</button>`;}
function renderLearn(){document.title='歴史・クイズ・身長計算機｜SKYLINE JAPAN';$('#app').innerHTML=`<div class="wrap"><div class="page-head"><p class="page-kicker">知ると、見上げるのがもっと楽しくなる</p><h1 tabindex="-1">歴史・クイズ・身長計算機</h1><p>日本一のビルの移り変わりをたどり、クイズや計算で高さを体感しよう。</p></div><nav class="page-subnav" aria-label="このページの目次"><a href="${U('learn/')}#learn-history">歴史年表</a><a href="${U('learn/')}#learn-future">建設中・計画中</a><a href="${U('learn/')}#learn-quiz">高さクイズ</a><a href="${U('learn/')}#learn-calculator">身長計算機</a></nav><section class="learn-section" id="learn-history"><h2>「日本一の座」の歴史</h2><p class="muted">竣工による代表的な首位交代を、年代順に紹介します。</p><div class="timeline">${history.map(([y,n,h,t])=>`<article><time datetime="${y}">${y}年</time><div><h3>${esc(n)}　<span class="num">${h}m</span></h3><p>${esc(t)}</p></div></article>`).join('')}</div><details class="data-note"><summary>年表の出典・高さの定義</summary><p>${link('https://www.kajima.co.jp/news/digest/apr_2018/feature/step/index-j.html','鹿島・超高層50年')}。霞が関ビルは最高部156m（軒高147m）で表示しています。着工や開業ではなく竣工による代表的な首位交代で、同年内の月日は省略しています。</p></details></section><section class="learn-section" id="learn-future"><h2>建設中・計画中の摩天楼</h2><p class="muted">まだランキングに含めていない、これからの高層ビル。</p><div class="future-grid"><article class="future-item"><span class="pill">建設中</span><h3>Torch Tower</h3><p>高さ385m・地上62階、2028年竣工予定。東京駅前の計画にはホテルや展望施設などが含まれます。</p>${link('https://office.mec.co.jp/search/detail/011527','三菱地所の計画情報')}</article><article class="future-item"><span class="pill">計画中</span><h3>六本木五丁目西地区</h3><p>約330mのメインタワーを計画。最上層部にはローズウッド東京の出店が発表されています。</p>${link('https://www.mori.co.jp/press/release/20260515_2/','森ビルの公式発表')}</article></div><p class="small muted">計画・高さ・竣工時期は変更になる場合があります。</p></section><section class="learn-section" id="learn-quiz"><h2>ミニクイズ「高いのはどっち？」</h2><p>高さの差が20m以上ある20問から、毎回ランダムに5問出題します。</p><div class="quizbox" id="quizbox"></div></section><section class="learn-section" id="learn-calculator"><h2>あなたの身長で、何人分？</h2><p>身長とビルを選ぶと、縦に並べた人数と、階段を登る時間の目安を計算します。</p><form id="calculator-form" class="calc-form">${field('person-height','あなたの身長（cm）','<input id="person-height" type="number" min="50" max="250" step="0.1" value="170" inputmode="decimal" required>')}${field('calc-building','比べるビル',`<select id="calc-building">${buildings.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select>`)}<button type="submit" class="button-primary">計算する</button></form><p id="calc-error" class="calc-error" role="alert"></p><div id="calc-results" aria-live="polite"></div><details class="data-note"><summary>計算方法・階段時間について</summary><p>人数＝ビルの高さ÷身長（m）。階段の時間は、段差17cm・毎分60段を仮定した「ビルの高さ÷0.17÷60」で算出しています。休憩・踊り場・階段の実際の形状を含まない単純な目安で、一般開放や階段での登頂を案内するものではありません。</p></details></section></div>`;startQuiz();calculate();}
function calculate(){const h=Number($('#person-height').value),b=buildings.find(b=>b.id===+$('#calc-building').value)||buildings[0];if(!Number.isFinite(h)||h<50||h>250){$('#calc-error').textContent='身長は50～250cmで入力してください。';$('#calc-results').innerHTML='';return;}$('#calc-error').textContent='';$('#calc-results').innerHTML=`<h3>${esc(b.name)}（${b.height}m）</h3><div class="calc-result"><div><small>身長${h}cmのあなたを縦に並べると</small><strong>約${(b.height/(h/100)).toFixed(1)}人分</strong></div><div><small>毎分60段で階段を登ると</small><strong>約${Math.round(b.height/.17/60)}分</strong></div></div><details class="data-note"><summary>全101棟の計算結果を見る</summary><table class="calc-table"><thead><tr><th>ビル</th><th>何人分</th><th>階段の目安</th></tr></thead><tbody>${buildings.map(x=>`<tr><td>${routeLink(x.id,x.name)}</td><td class="num">${(x.height/(h/100)).toFixed(1)}人</td><td class="num">約${Math.round(x.height/.17/60)}分</td></tr>`).join('')}</tbody></table></details>`;}
function scrollToRoute(section,page,id){requestAnimationFrame(()=>{const key=page==='building'?`b${id}-${section}`:page==='learn'?`learn-${section}`:section==='method'?'ranking-method':'';const el=key?document.getElementById(key):null;if(el){if(el.tagName==='DETAILS')el.open=true;el.scrollIntoView({block:'start',behavior:'instant'});}else if(page==='ranking')window.scrollTo({top:homeScroll,behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});});}
function route(){let rel=location.pathname;rel=rel.startsWith(BASE)?rel.slice(BASE.length):rel.replace(/^\//,'');const parts=rel.replace(/index\.html$/,'').split('/').filter(Boolean),page=parts[0]==='method'?'method':['building','visit','compare','learn'].includes(parts[0])?parts[0]:'ranking',id=page==='building'?Number(parts[1]):null,hash=decodeURIComponent(location.hash.slice(1)),section=page==='method'?'method':page==='building'?(hash.startsWith('b'+id+'-')?hash.slice(String('b'+id+'-').length):undefined):page==='learn'?(hash.startsWith('learn-')?hash.slice(6):undefined):undefined;if(currentPage==='ranking'&&page!=='ranking')homeScroll=window.scrollY;const sameBuilding=page==='building'&&currentPage===page&&currentBuilding===id,sameLearn=page==='learn'&&currentPage===page;if(!sameBuilding&&!sameLearn){if(page==='building')renderBuilding(id);else if(page==='visit')renderGuide();else if(page==='compare')renderCompare();else if(page==='learn')renderLearn();else if(page==='method')renderMethod();else{renderHome();document.title='SKYLINE JAPAN｜日本の超高層ビルランキング100';}}if(!sameBuilding&&!sameLearn)requestAnimationFrame(()=>$('#app h1')?.focus({preventScroll:true}));currentPage=page;$$('.primary-nav a').forEach(a=>{if(a.dataset.page===(['building','method'].includes(page)?'ranking':page))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$$('[data-section]').forEach(a=>a.classList.toggle('active',a.dataset.section===(section||'overview')));scrollToRoute(section,page,id);const cl=document.querySelector('link[rel=canonical]');if(cl&&!window.__SKYLINE_BASE__)cl.href=location.origin+location.pathname;}
function setSort(key){if(state.sort===key)state.dir=state.dir==='asc'?'desc':'asc';else{state.sort=key;state.dir=['name','city','rank'].includes(key)?'asc':'desc';}renderResults();}
function resetFilters(){state={...defaults,view:state.view};saveState();renderHome();}
$('#app').addEventListener('click',async e=>{const el=e.target.closest('button,[data-reset]');if(!el)return;if(el.dataset.sort){setSort(el.dataset.sort);return}if(el.dataset.view){state.view=el.dataset.view;renderResults();return}if(el.id==='reset-filters'||el.hasAttribute('data-reset')){resetFilters();return}if(el.dataset.photoId){const b=buildings.find(b=>b.id===+el.dataset.photoId);$('#photo-body').innerHTML=`${photo(b,'',false)}<p>${credit(b.image)}</p>`;$('#photo-dialog').showModal();return}if(el.dataset.choice){answerQuiz(+el.dataset.choice);return}if(el.hasAttribute('data-quiz-next')){qi++;renderQuiz();return}if(el.hasAttribute('data-quiz-restart')){startQuiz();return}if(el.hasAttribute('data-copy-url')){try{await navigator.clipboard.writeText(location.origin+U('building/'+currentBuilding+'/'));$('#copy-status').textContent='コピーしました'}catch(err){$('#copy-status').textContent='アドレスバーのURLから共有できます'}}});
$('#app').addEventListener('input',e=>{if(e.target.id==='building-search'){state.q=e.target.value;$('#header-search').value=state.q;renderResults();animateHeroCount();}});
$('#app').addEventListener('change',e=>{const id=e.target.id,key={city:'city',access:'access',decade:'decade',developer:'developer',contractor:'contractor',use:'use','rank-range':'range','hotel-only':'hotel'}[id];if(key){state[key]=id==='hotel-only'?e.target.checked:e.target.value;renderResults();}else if(id==='mobile-sort'&&e.target.value){[state.sort,state.dir]=e.target.value.split(':');renderResults();}else if(id==='guide-city'){guideCity=e.target.value;renderGuideResults();}else if(id==='guide-free'){guideFree=e.target.checked;renderGuideResults();}else if(id==='guide-night'){guideNight=e.target.checked;renderGuideResults();}else if(id==='compare-mode'){comparisonMode=e.target.value||'top20';renderSilhouettes();}else if(id==='compare-building'){comparisonId=e.target.value;comparisonMode='single';$('#compare-mode').value='single';renderSilhouettes();}});
$('#app').addEventListener('submit',e=>{if(e.target.id==='calculator-form'){e.preventDefault();calculate();}});
$('#header-search-form').addEventListener('submit',e=>{e.preventDefault();state.q=$('#header-search').value;saveState();if(currentPage!=='ranking'){navigate(U(''))}else{const search=$('#building-search');if(search)search.value=state.q;renderResults();$('#rank-results').scrollIntoView({block:'start',behavior:'instant'});}});
$('#header-search').addEventListener('input',e=>{if(currentPage==='ranking'){state.q=e.target.value;$('#building-search').value=state.q;renderResults();}});
$('#photo-close').addEventListener('click',()=>$('#photo-dialog').close());$('#photo-dialog').addEventListener('click',e=>{if(e.target===$('#photo-dialog'))$('#photo-dialog').close()});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/')){window.history.replaceState(null,'',hashToPath(location.hash));route();}});
window.addEventListener('popstate',()=>route());
document.addEventListener('click',e=>{if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const a=e.target.closest&&e.target.closest('a[href]');if(!a||a.target||a.hasAttribute('download'))return;const raw=a.getAttribute('href');if(!raw||raw.startsWith('#'))return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!u.pathname.startsWith(BASE)||!/\/$/.test(u.pathname))return;e.preventDefault();if(u.href===location.href){route();return;}navigate(u.href);});
function updatePhotoState(img,loaded){const frame=img.closest('.photo-frame');if(!frame)return;frame.dataset.photoState=loaded?'loaded':'error';const label=frame.querySelector('.photo-label');if(label&&!loaded)label.textContent='写真を表示できません';}
document.addEventListener('load',e=>{if(e.target.matches?.('[data-building-photo]'))updatePhotoState(e.target,true);},true);
document.addEventListener('error',e=>{if(e.target.matches?.('[data-building-photo]'))updatePhotoState(e.target,false);},true);
let heroCountAnimated=false;
function animateHeroCount(){const el=$('#hero-count');if(!el)return;const target=buildings[0].height;el.textContent=target.toFixed(2);if(heroCountAnimated||window.matchMedia('(prefers-reduced-motion: reduce)').matches||window.matchMedia('(max-width:680px)').matches)return;heroCountAnimated=true;el.textContent='0.00';const start=performance.now();function step(now){if(el.isConnected===false)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=target.toFixed(2);return;}const t=Math.min(Math.max((now-start)/800,0),1);el.textContent=(target*(1-Math.pow(1-t,3))).toFixed(2);if(t<1)requestAnimationFrame(step);}requestAnimationFrame(step);}

if(location.hash.startsWith('#/'))window.history.replaceState(null,'',hashToPath(location.hash));
route();
